PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE persons (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        first_name TEXT,
        middle_name TEXT,
        last_name TEXT,
        party_name TEXT,
        office TEXT,
        district TEXT,
        popolo_json TEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE social_accounts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        person_id TEXT NOT NULL,
        platform TEXT NOT NULL,
        profile_url TEXT NOT NULL,
        label TEXT,
        confidence REAL NOT NULL,
        confidence_level TEXT NOT NULL,
        rationale TEXT,
        signals TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (person_id) REFERENCES persons(id) ON DELETE CASCADE,
        UNIQUE(person_id, platform, profile_url)
    );
CREATE INDEX idx_persons_name ON persons(name);
CREATE INDEX idx_persons_party ON persons(party_name);
CREATE INDEX idx_persons_district ON persons(district);
CREATE INDEX idx_social_person_id ON social_accounts(person_id);
CREATE INDEX idx_social_platform ON social_accounts(platform);
CREATE INDEX idx_social_confidence ON social_accounts(confidence_level);
COMMIT;
